<div class="d-flex justify-content-between align-items-center mb-3"><div><h3><?= e($title) ?></h3><div class="text-muted">الطلب: <?= e($request['request_number']??'') ?> · <?= e($conversation['customer_name']??'') ?> ↔ <?= e($conversation['provider_name']??'') ?></div></div><?php renderBackButton($backUrl ?? null, 'رجوع'); ?></div><div class="card p-3 mb-3" style="max-height:480px;overflow:auto"><?php foreach($messages as $m): ?><div class="mb-3 <?= $m['sender_id']==Auth::id()?'text-end':'' ?>"><div class="small text-muted"><?= e($m['sender_name']) ?> · <?= e($m['created_at']) ?></div><div class="d-inline-block bg-light border rounded p-2 mt-1" style="max-width:80%;white-space:pre-line"><?= e($m['message']) ?></div></div><?php endforeach; if(!$messages): ?><div class="text-center text-muted py-5">لا توجد رسائل بعد.</div><?php endif; ?></div><?php if(empty($readOnly)): ?><form method="post" class="card p-3"><?= csrf_field() ?><textarea name="message" class="form-control" rows="3" maxlength="4000" placeholder="اكتب رسالتك..." required></textarea><button class="btn btn-primary mt-2">إرسال الرسالة</button></form><?php else: ?><div class="alert alert-info">عرض متابعة للموظف — لا يمكنه إرسال رسالة من هذه الشاشة.</div><?php endif; ?>